return items.map((item) => {
  const raw = item.json.choices[0].message.content;
  const clean = raw.replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(clean);

  const originalIndex = item.pairedItem.item;
  const original = $('Get many messages').all()[originalIndex].json;

  return {
    json: {
      from: original.From,
      subject: original.Subject,
      priority: parsed.priority,
      summary: parsed.summary,
      reason: parsed.reason
    }
  };
});

const items_in = items;

const order = { '🔴': 0, '🟡': 1, '🟢': 2 };
items_in.sort((a, b) => order[a.json.priority] - order[b.json.priority]);

let message = `📬 *Morning Digest — ${new Date().toDateString()}*\n\n`;

const counts = { '🔴': 0, '🟡': 0, '🟢': 0 };
items_in.forEach(item => counts[item.json.priority]++);
message += `${counts['🔴']} need reply · ${counts['🟡']} FYI · ${counts['🟢']} can wait\n\n`;

items_in.forEach(item => {
  const { priority, from, subject, summary } = item.json;
  const fromName = from.split('<')[0].trim();
  message += `${priority} *${fromName}*\n${summary}\n\n`;
});

return [{ json: { message } }];
